async function discoverAssets(){if(assetsBusy)return;assetsBusy=true;try{const ctl=new AbortController(),t=setTimeout(()=>ctl.abort(),20000);const r=await fetch(PUBLIC_BASE+'/trading-variables/pairs,groups,pairInfos',{signal:ctl.signal});clearTimeout(t);if(!r.ok)throw Error('HTTP '+r.status);const {pairs,groups,pairInfos}=await r.json();const list=pairs.map((p,i)=>{const g=groups[+p.groupIndex];const over=+((pairInfos.maxLeverages||[])[i]||0)/1e3;const max=over===0?+g.maxLeverage/1e3:over;return {pairIndex:i,symbol:String(p.from).split('_')[0]+'/'+p.to,maxLeverage:max,group:String(g.name).replace(/-\d+$/,'').replace(/^altcoins$/,'crypto'),_min:+g.minLeverage/1e3};}).filter(a=>a.maxLeverage>=a._min);const n=TradeConfig.discover(list);assetsAt=Date.now();if(n>0){renderMarketList();}return n;}catch{}finally{assetsBusy=false;}}
