function renderAccount(){if($('accountPanel').hidden)return;const ps=mode==='paper'?book.positions:livePositions;const rows=accountPage==='history'?(mode==='paper'?book.history:liveHistory.filter(p=>wallet&&p.owner?.toLowerCase()===wallet.address.toLowerCase())):ps;const collateral=ps.reduce((s,p)=>s+p.amount,0),notional=ps.reduce((s,p)=>s+p.amount*p.lev,0);const values=ps.map(p=>mode==='paper'?Engine.value(p,priceOf(p.pair)||p.entry).net:liveValue(p));const net=values.every(Number.isFinite)?values.reduce((s,v)=>s+v,0):NaN;const cash=mode==='paper'?book.cash:liveBalance;const equity=Number.isFinite(cash)&&Number.isFinite(net)?cash+collateral+net:NaN;$('accountTitle').textContent=accountPage==='history'?'Past trades':'Portfolio';$('accountSummary').textContent=`${mode.toUpperCase()} · Available ${money(cash)} · Collateral ${money(collateral)} · Notional ${money(notional)} · Net ${money(net)} · Equity ${money(equity)} (estimated)`;$('accountRows').innerHTML=rows.map(p=>{const v=accountPage==='history'?p.net:mode==='paper'?Engine.value(p,priceOf(p.pair)||p.entry).net:liveValue(p);return `<article class="account-row"><b>${esc(marketLabel(p.pair))}</b> <b class="${p.long?'long':'short'}">${p.long?'LONG':'SHORT'} ${p.lev}×</b><p>Collateral ${money(p.amount)} · Entry ${money(p.entry)}${accountPage==='history'?' · Exit '+money(p.exit):''}</p><b class="${Number.isFinite(v)&&v<0?'negative':'positive'}">${accountPage==='history'?'Settled':'Estimated'} P&L ${money(v)}</b><small>${esc(p.status||'Open')}${p.closed?' · '+esc(new Date(p.closed).toLocaleString()):''}</small></article>`}).join('')||'<p class="muted">No '+(accountPage==='history'?'past trades':'open positions')+' across any market.</p>';$('accountPortfolio').className=accountPage==='portfolio'?'active':'';$('accountHistory').className=accountPage==='history'?'active':'';}
