function renderFees(){try{const el=$('fees');if(!el)return;const m=TradeConfig.marketOrNull(pair),f=marketFees[pair],rates=f&&Number.isFinite(f.borrowHourly)&&Date.now()-(f.at||0)<180000;el.textContent=`${m?m.symbol:pair} · ${rates?'Borrow '+f.borrowHourly+'%/h · Fund L '+f.fundLongHourly+'%/h / S '+f.fundShortHourly+'%/h (Polygon)':'Holding rates unavailable · paper assumptions'} · Base open/close ${paperCosts(pair,true).fee}%${f&&Number.isFinite(f.feePct)?' (Polygon)':' (estimate)'} · negative funding = earned`; }catch{}}

/* Hourly holding rates (docs: holding-rates). Polygon chainId 137 first,
 * backend-global mirror, then Arbitrum markets API as last resort. */
async function fetchHoldingRates(pi){const urls=[`${PUBLIC_BASE}/api/holding-rates/3/${pi}?chainId=137`,'https://backend-global.gains.trade/api/holding-rates/3/'+pi+'?chainId=137'];for(const u of urls){try{const ctl=new AbortController(),t=setTimeout(()=>ctl.abort(),15000);const r=await fetch(u,{signal:ctl.signal});clearTimeout(t);if(!r.ok)continue;const j=await r.json();const rows=j.holdingRates||j.data||j;if(!Array.isArray(rows)||!rows.length)continue;const lastRow=rows[rows.length-1];const b=Number(lastRow.borrowingFeeV2HourlyRate),fL=Number(lastRow.fundingFeeLongHourlyRate),fS=Number(lastRow.fundingFeeShortHourlyRate);if(![b,fL,fS].every(Number.isFinite)||b<0)continue;marketFees[pi]={borrowHourly:+(b*100).toFixed(6),fundLongHourly:+(fL*100).toFixed(6),fundShortHourly:+(fS*100).toFixed(6),feePct:marketFees[pi]?.feePct??NaN,at:Date.now(),src:'Polygon holding-rates'};marketFeesAt=Date.now();renderFees();return true;}catch{}}return false;}
function paperCosts(pi,long){const f=marketFees[pi],c={...cfg};if(f&&Number.isFinite(f.feePct))c.fee=f.feePct;else if(TradeConfig.marketOrNull(pi)?.degen)c.fee=.02;if(f&&Number.isFinite(f.spreadPct))c.slip=f.spreadPct;else if([300,313,327].includes(pi))c.slip=0;if(f&&Date.now()-(f.at||0)<180000&&Number.isFinite(f.borrowHourly)){c.borrow=f.borrowHourly;c.fundingSide=long?f.fundLongHourly:f.fundShortHourly;}return c;}
async function fetchMarketFees(){const pi=pair;await fetchHoldingRates(pi);try{const c=await chain();const [fee,registered]=await Promise.all([c.pairTotalPositionSizeFeeP(pi),c.pairs(pi)]);marketFees[pi]={...marketFees[pi],feePct:N(fee)/1e10,spreadPct:N(registered.spreadP)/1e10,src:'Polygon contract + holding-rates'};renderFees();}catch{/* Retain explicit paper assumptions when Polygon is unavailable. */}}


