function syncNative(){if(!window.Feed)return;try{const caps=JSON.stringify(TradeConfig.allMarkets().map(m=>({pairIndex:m.pairIndex,maxLeverage:m.maxLeverage})));if(caps!==nativeCaps&&Feed.updateCaps){Feed.updateCaps(caps);nativeCaps=caps;}}catch{}try{const s=JSON.parse(Feed.snapshot());const prevPx={};for(const k of Object.keys(prices))prevPx[k]=prices[k];const prevTail=(candles[pair]||[]).slice(-1)[0]||null;const nowMs=Date.now();if(Array.isArray(s.prices)){for(let k=0;k<2;k++){const v=s.prices[k]||0,t=(Array.isArray(s.times)?s.times[k]:0)||0;if(v>0&&nowMs-t<10000){prices[k]=v;last[k]=t;}}}if(s.indexPrices)for(const k of Object.keys(s.indexPrices)){const v=+s.indexPrices[k],t=+((s.indexTimes||{})[k]||0);if(Engine.freshQuote(v,t)){indexPrices[k]=v;indexTimes[k]=t;}}if(s.pricesByPair)for(const k of Object.keys(s.pricesByPair)){const v=+s.pricesByPair[k]||0,t=+((s.timesByPair||{})[k]||0);if(v>0&&nowMs-t<10000){prices[k]=v;last[k]=t;}}if(Array.isArray(s.candles)){candles[0]=Engine.mergeCandles(candles[0],s.candles[0]||[]);candles[1]=Engine.mergeCandles(candles[1],s.candles[1]||[]);}if(s.candlesByPair)for(const k of Object.keys(s.candlesByPair))candles[k]=Engine.mergeCandles(candles[k],s.candlesByPair[k]);try{candles[pair]=Engine.dedupeCandles(candles[pair]);}catch{}
/* Native bridge moves make the same sounds as socket moves. */
try{if(prevPx[pair]>0&&priceOf(pair)>0&&priceOf(pair)!==prevPx[pair]){onTick(prevPx[pair],priceOf(pair));checkCrossings(prevPx[pair],priceOf(pair));}const tail=(candles[pair]||[]).slice(-1)[0]||null;if(prevTail&&tail&&tail.t!==prevTail.t&&Number.isFinite(prevTail.o)&&Number.isFinite(prevTail.c))onCandleClose(prevTail);}catch{}
book=JSON.parse(Feed.paper());try{$('historyStatus').textContent=s.history;}catch{}try{$('keepAlive').checked=s.running;}catch{}}catch{}}
async function fetchHistoryChain(chain,apiSym,from,to){const ctl=new AbortController(),timer=setTimeout(()=>ctl.abort(),15000);try{const r=await fetch(`https://api.gains.trade/v1/${chain}/markets/${apiSym}/candles?interval=1m&from=${from}&to=${to}`,{signal:ctl.signal});if(!r.ok)throw Error('History HTTP '+r.status+' ('+chain+')');try{const n=+r.headers.get('content-length')||15000;rxWindow+=n;rxBytes+=n;}catch{}return {rows:Engine.history((await r.json()).data),chain};}finally{clearTimeout(timer);}}
/* Reference price for PnL display: live oracle first, else latest candle
 * close, so colors/percentages show even before a feed tick arrives. */
function refPrice(p){const live=priceOf(p);if(live>0)return live;try{const a=candlesOf(p);if(a.length&&a[a.length-1].c>0)return a[a.length-1].c;}catch{}return 0;}
const historyLoading=new Set();
async function loadHistory(targetPair=pair){if(historyLoading.has(targetPair))return;historyLoading.add(targetPair);try{const m=TradeConfig.marketOrNull(targetPair);const apiSym=m?TradeConfig.apiSymbol(m):(targetPair?'ETH':'BTC')+'-USD';const to=Date.now(),from=to-300*60000;let got=null;try{got=await fetchHistoryChain('polygon',apiSym,from,to);}catch(e1){try{got=await fetchHistoryChain('arbitrum',apiSym,from,to);}catch(e2){throw e1;}}candles[targetPair]=Engine.mergeCandles(candlesOf(targetPair),got.rows);if(targetPair===pair&&snapshotBusy)setLoadBar(38,'History loaded · drawing…');else if(targetPair===pair)setLoadBar(100,'Ready');try{if(targetPair===pair)$('historyStatus').textContent=candles[targetPair].length?`Gains history + live · 1m (${got.chain})`:'Waiting for live prices · history empty';}catch{}}catch{try{if(targetPair===pair)$('historyStatus').textContent='History unavailable · live only · retrying';}catch{}if(targetPair===pair)setLoadBar(100,'History pending · live only');setTimeout(()=>loadHistory(targetPair),30000)}finally{historyLoading.delete(targetPair);}}
