async function getPublicJson(path){const ctl=new AbortController(),timer=setTimeout(()=>ctl.abort(),15000);try{const r=await fetch(PUBLIC_BASE+path,{signal:ctl.signal});if(!r.ok)throw Error('Gains backend HTTP '+r.status);return await r.json()}finally{clearTimeout(timer)}}
async function getChainJson(net,path,ms){const ctl=new AbortController(),timer=setTimeout(()=>ctl.abort(),ms||15000);try{const r=await fetch(net.host+path,{signal:ctl.signal});if(!r.ok)throw Error(net.name+' HTTP '+r.status);return await r.json()}finally{clearTimeout(timer)}}
const CHAINS=[{name:'POLYGON',host:PUBLIC_BASE},{name:'ARBITRUM',host:'https://backend-arbitrum.gains.trade'},{name:'BASE',host:'https://backend-base.gains.trade'}];
const COLLATERAL_DECIMALS={1:18,2:18,3:6,4:18};
let loadHideT=0;
function setLoadBar(pct,msg){try{const bar=$('loadbar'),fill=$('loadfill');if(!bar||!fill)return;if(barRetired&&pct<100)return;bar.hidden=false;fill.style.width=Math.max(0,Math.min(100,pct))+'%';if(msg!=null)$('loadmsg').textContent=msg;clearTimeout(loadHideT);if(pct>=100){barRetired=true;loadHideT=setTimeout(()=>{try{bar.hidden=true;}catch{}},700);}}catch{}}
let reloadAt=0,reloadTimer=0,snapStartAt=0,loadAttempts=0,fullyLoaded=false,barRetired=false;
function queuePublicReload(){const now=Date.now();if(snapshotBusy)return;if(reloadTimer)return;reloadTimer=setTimeout(()=>{reloadTimer=0;reloadAt=Date.now();loadPublicSnapshot();},2500);}
function sdkPublic(raw,previous,net){const t=raw.trade;if(!t||!displayablePair(N(t.pairIndex))||!t.isOpen||N(t.tradeType)!==0)return null;const p={...previous,...normalize(t),kind:'public',container:raw,isOpen:true,net:net||(previous&&previous.net)||'POLYGON'};p.id=p.net+':'+t.user.toLowerCase()+':'+N(t.index);const ci=N(t.collateralIndex);if(publicVars&&p.net==='POLYGON'){const col=publicVars.globalTradingVariables.collaterals[ci-1];if(col)p.amount=N(t.collateralAmount)/10**col.collateralConfig.decimals*(col.prices?.collateralPriceUsd||1);else p.amount=N(t.collateralAmount)/10**(COLLATERAL_DECIMALS[ci]||18);}else p.amount=N(t.collateralAmount)/10**(COLLATERAL_DECIMALS[ci]||18);return p;}
function recalcPublic(){if(!publicVars)return;const g=publicVars.globalTradingVariables;for(const p of publicTrades){if(p.net&&p.net!=='POLYGON')continue;if(!p.isOpen||!p.container||!priceOf(p.pair))continue;try{const t=GainsMath.convertTradeContainer(p.container,g.collaterals);if(!t.tradeFeesData&&t.tradeInfo.contractsVersion<2)t.tradeFeesData={realizedPnlCollateral:0,realizedTradingFeesCollateral:0};const ctx=GainsMath.buildLiquidationPriceContext(g,t,{currentBlock:publicVars.blockNumber,currentTimestamp:Math.floor(Date.now()/1000),currentPairPrice:(indexPrices[p.pair]||priceOf(p.pair)),spreadP:g.pairs[p.pair]?g.pairs[p.pair].spreadP:0,traderFeeMultiplier:1});const liq=GainsMath.getLiquidationPrice(t.trade,ctx);if(!Number.isFinite(liq)||liq<=0)throw Error('Liquidation unavailable');p.liq=liq;p.liqTime=Date.now();p.liqError=false;}catch{p.liqError=true}}renderPublic();}
let liqBusy=false;
/* Polygon-only contract liq backfill for the nearest liq-less lines.
 * Used when the backend vars/SDK math is unavailable (verified v10 shape
 * mismatch) so pink LIQ lines still appear. */
async function backfillPublicLiq(){if(liqBusy)return;liqBusy=true;try{const c=await chain();const near=publicTrades.filter(p=>p.isOpen&&p.net==='POLYGON'&&!p.liq&&priceOf(p.pair)).sort((a,b)=>Math.abs(a.entry-priceOf(a.pair))-Math.abs(b.entry-priceOf(b.pair))).slice(0,12);for(const p of near){try{const t=p.container?p.container.trade:p.raw;if(!t||!t.user)continue;const lp=await c.getTradeLiquidationParams(t.user,t.index);const v=await c.getTradeLiquidationPrice({collateralIndex:t.collateralIndex,trader:t.user,pairIndex:t.pairIndex,index:t.index,openPrice:t.openPrice,long:t.long,collateral:t.collateralAmount,leverage:t.leverage,additionalFeeCollateral:0,liquidationParams:lp,currentPairPrice:priceUnit(priceOf(p.pair)),isCounterTrade:t.isCounterTrade,partialCloseMultiplier:1e10,beforeOpened:false});const liq=N(v)/1e10;if(liq>0){p.liq=liq;p.liqError=false;renderPublic();}}catch{}}}catch{}finally{liqBusy=false;}}
let firstPublicDone=false;
async function loadPublicSnapshot(manual){if(snapshotBusy){if(Date.now()-(snapStartAt||0)>90000)snapshotBusy=false;else return;}snapshotBusy=true;snapStartAt=Date.now();loadAttempts++;const loud=(manual===true)||(!firstPublicDone&&loadAttempts<=3);if(loud)setLoadBar(6,'Loading open trades · Polygon + Arbitrum + Base…');
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
try{
const revision=publicRevision;const old=new Map(publicTrades.map(p=>[p.id,p]));
const next=[];let skipped=0;const perNet={};const chainErr=[];
const keyOf=(net,raw)=>{try{return net+':'+raw.trade.user.toLowerCase()+':'+N(raw.trade.index);}catch{return net+':?';}};
/* Each chain streams independently: a slow chain never blocks the others. */
const doChain=async net=>{let rows;try{rows=await getChainJson(net,'/open-trades',20000);if(!Array.isArray(rows)||rows.some(r=>!r?.trade?.user||r.trade.index===undefined))throw Error('Invalid open-trades snapshot');}catch(e){chainErr.push(net.name+' '+String((e&&e.message)||e));return;}let idx=0;const total=rows.length;while(idx<total){const end=Math.min(idx+60,total);for(;idx<end;idx++){try{const p=sdkPublic(rows[idx],old.get(keyOf(net.name,rows[idx])),net.name);if(p){next.push(p);perNet[p.net]=(perNet[p.net]||0)+1;}else skipped++;}catch{skipped++;}}if(loud){setLoadBar(6+Math.round(54*next.length/Math.max(1,total)),`Loading open trades… ${next.length} so far`);}await sleep(40);}};
await Promise.all(CHAINS.map(doChain));
const okNets=new Set();for(const r of [{net:'POLYGON'},{net:'ARBITRUM'},{net:'BASE'}])okNets.add(r.net);
for(const line of chainErr.map(e=>e.split(' ')[0]))okNets.delete(line);
for(const q of publicTrades){if(!okNets.has(q.net||'POLYGON')&&!next.some(w=>w.id===q.id))next.push(q);}
const errs=chainErr.join('; ');
snapId++;const capped=mergePublicSnapshot(next,okNets,revision);const wasFirst=!firstPublicDone;notePublicDiff(capped,true);publicTrades=capped;
if(wasFirst&&capped.length)pushEvent(`Tracking ${capped.length} live open trades`,'');
if(loud)setLoadBar(70,'Computing liquidations…');
try{let vars=null,verr=null;for(const u of ['/trading-variables/all','/trading-variables']){try{vars=await getChainJson(CHAINS[0],u,20000);break;}catch(e){verr=e;}}if(!vars)throw verr||Error('vars unavailable');try{publicVars=GainsMath.transformGlobalTradingVariables(vars);publicVarsAt=Date.now();}catch(e){publicVars=null;throw Error('liq math unavailable ('+((e&&e.message)||'backend too new').slice(0,60)+')');}recalcPublic();}
catch(e){try{$('publicStatus').textContent='Entries live · '+e.message+' · contract liq backfill running';}catch{}try{backfillPublicLiq();}catch{}}
const counts=`POL ${perNet.POLYGON||0} · ARB ${perNet.ARBITRUM||0} · BASE ${perNet.BASE||0}`;
if(next.length||publicTrades.length)firstPublicDone=true;
try{$('publicStatus').textContent=`${publicTrades.length} open traders (${counts})${skipped?` · skipped ${skipped}`:''}${errs?' · '+errs:''} · tap a trader to focus`;renderMarketList();}catch{}renderPublic();if(loud)setLoadBar(100,'Ready');
}catch(e){try{$('publicStatus').textContent='Trader snapshot unavailable: '+e.message;}catch{}if(!publicTrades.length){try{await loadPublicFromChain()}catch(err){try{$('publicStatus').textContent+=' · RPC fallback unavailable';}catch{}}}else{try{$('publicStatus').textContent+=' · keeping previous lines';}catch{}}if(loud)setLoadBar(100,'Offline — retrying');}finally{snapshotBusy=false}}
async function loadPublicFromChain(){const c=await chain(),found=[];for(let offset=0;;offset+=100){const trades=await c.getAllTrades(offset,100);for(const t of trades)if(t.isOpen&&N(t.tradeType)===0&&displayablePair(N(t.pairIndex))){const p={...normalize(t),kind:'public',isOpen:true,net:'POLYGON'};p.id='POLYGON:'+p.id;if(N(t.collateralIndex)!==3){const col=await c.getCollateral(t.collateralIndex),usd=await c.getCollateralPriceUsd(t.collateralIndex);p.amount=N(t.collateralAmount)/N(col.precision)*N(usd)/1e8}try{const lp=await c.getTradeLiquidationParams(t.user,t.index);p.liq=N(await c.getTradeLiquidationPrice({collateralIndex:t.collateralIndex,trader:t.user,pairIndex:t.pairIndex,index:t.index,openPrice:t.openPrice,long:t.long,collateral:t.collateralAmount,leverage:t.leverage,additionalFeeCollateral:0,liquidationParams:lp,currentPairPrice:priceUnit(priceOf(p.pair)||p.entry),isCounterTrade:t.isCounterTrade,partialCloseMultiplier:1e10,beforeOpened:false}))/1e10}catch{p.liqError=true}found.push(p)}if(trades.length<100)break}notePublicDiff(found.slice());publicTrades=mergePublicSnapshot(found,new Set(['POLYGON']),publicRevision);renderPublic();try{$('publicStatus').textContent=`${found.length} open traders · Polygon snapshot`;}catch{}}
function setupPublicBackend(){loadPublicSnapshot();if(publicSocket)try{publicSocket.close();}catch{}let s;try{s=new WebSocket('wss://backend-polygon.gains.trade');}catch(e){try{$('publicStatus').textContent='Trade stream blocked · retrying';}catch{}const d=Math.min(30000,2500*Math.pow(2,publicRetry++));setTimeout(setupPublicBackend,d);return;}publicSocket=s;publicSocket.onmessage=e=>{try{publicRetry=0;rxBytes+=e.data.length;rxWindow+=e.data.length;const msg=JSON.parse(e.data);if(s!==publicSocket)return;applyBackendChange(msg,'POLYGON');if(msg.name==='currentBlock'&&publicVars){publicVars.blockNumber=Number(msg.value);return}if(['registerTrade','unregisterTrade','updateTrade','updateLeverage','updatePositionSize','deepReorg','tradingVariables','liveEvents'].includes(msg.name)){pushGlobalLive(msg,'POLYGON');if(msg.name==='tradingVariables')discoverAssets();if(!publicRefreshTimer)publicRefreshTimer=setTimeout(()=>{publicRefreshTimer=0;queuePublicReload()},1200)}}catch{}};publicSocket.onclose=()=>{if(s!==publicSocket)return;const d=Math.min(30000,2500*Math.pow(2,publicRetry++));try{$('publicStatus').textContent='Trade stream retrying…';}catch{}setTimeout(setupPublicBackend,d);};publicSocket.onerror=()=>{};}
